const raw = items[0].json;
const payload = raw.body && (Array.isArray(raw.body.alerts) || raw.body.status) ? raw.body : raw;
const alerts = Array.isArray(payload.alerts) ? payload.alerts : [];

function labelText(labels) {
  const source = labels || {};
  const where = [source.namespace, source.pod || source.node || source.instance].filter(Boolean);
  return where.length ? ' (' + where.join('/') + ')' : '';
}

function describe(alert) {
  const labels = alert.labels || {};
  const name = labels.alertname || 'alert';
  const annotations = alert.annotations || {};
  const summary = annotations.summary || annotations.description || '';
  const head = name + labelText(labels);
  return summary ? head + ': ' + summary : head;
}

const firing = alerts.filter(function (alert) { return alert.status === 'firing'; });
const resolved = alerts.filter(function (alert) { return alert.status === 'resolved'; });
const sections = [];
if (firing.length) sections.push('Firing:\n' + firing.map(describe).join('\n'));
if (resolved.length) sections.push('Resolved:\n' + resolved.map(describe).join('\n'));
if (!sections.length) return [];

const seen = {};
const fingerprints = [];
alerts.forEach(function (alert) {
  if (!alert.fingerprint || seen[alert.fingerprint]) return;
  seen[alert.fingerprint] = true;
  fingerprints.push(alert.fingerprint);
});
fingerprints.sort();
const idempotencyKey = fingerprints.length ? fingerprints.join(',') : String(payload.groupKey || 'alert');

const common = payload.commonLabels || {};
const firstAlert = firing[0] || alerts[0] || {};
const firstLabels = firstAlert.labels || {};
const labelSource = Object.keys(common).length ? common : firstLabels;
const matchers = Object.keys(labelSource).map(function (name) {
  return {
    name: name,
    value: String(labelSource[name]),
    isRegex: false,
    isEqual: true,
  };
});
if (!matchers.length) return [];

return [{
  json: {
    text: sections.join('\n\n'),
    matchers: matchers,
    idempotencyKey: idempotencyKey,
  },
}];
